fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    // If there are fewer than 2 elements, nothing to do.
    if numbers.len() <= 1 {
        return numbers;
    }

    // Pre-allocate the exact required capacity: 2*n - 1
    let n = numbers.len();
    let mut result = Vec::with_capacity(2 * n - 1);

    // Insert the first element
    let mut iter = numbers.into_iter();
    if let Some(first) = iter.next() {
        result.push(first);
    }

    // For each remaining element, first insert the delimiter, then the element
    for num in iter {
        result.push(delimiter);
        result.push(num);
    }

    result
}

